"""
Zscaler Cleanup Proposal Documents Generator

PowerShell:
    python zscaler_proposal_generator.py

Output (in current directory):
    - URL_Filtering_Cleanup_Proposal.docx
    - SSL_Inspection_Cleanup_Proposal.docx

No dependencies required beyond Python standard library.
"""

import base64, zlib, os, sys

_URL = """"""

_SSL = """"""

def main():
    d = os.getcwd()
    for name, data in [("URL_Filtering_Cleanup_Proposal.docx", _URL), ("SSL_Inspection_Cleanup_Proposal.docx", _SSL)]:
        path = os.path.join(d, name)
        with open(path, "wb") as f:
            f.write(zlib.decompress(base64.b64decode(data)))
        print(f"Saved: {path}")
    print("\nDone!")

if __name__ == "__main__":
    main()
